from datetime import date, timedelta
from typing import List, Optional

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = holidays or []
        # Track used leave days per employee per year
        self.used_days = {}  # {employee: {year: days_used}}

    def _is_weekend(self, d: date) -> bool:
        return d.weekday() >= 5  # Saturday=5, Sunday=6

    def _is_holiday(self, d: date) -> bool:
        return d in self.holidays

    def _is_working_day(self, d: date) -> bool:
        return not self._is_weekend(d) and not self._is_holiday(d)

    def _get_used_days(self, employee: str, year: int) -> int:
        return self.used_days.get(employee, {}).get(year, 0)

    def _set_used_days(self, employee: str, year: int, days: int) -> None:
        if employee not in self.used_days:
            self.used_days[employee] = {}
        self.used_days[employee][year] = days

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        # Requirement 3: end date before start date
        if end < start:
            raise ValueError("End date must be on or after start date")

        # Requirement 1: request made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date")

        # Calculate the number of working days in the requested period
        current = start
        working_days = 0
        while current <= end:
            if self._is_working_day(current):
                working_days += 1
            current += timedelta(days=1)

        # Requirement 4: check if employee has enough remaining days
        year = start.year
        used_so_far = self._get_used_days(employee, year)
        remaining = self.days_per_year - used_so_far

        if working_days > remaining:
            raise ValueError("Not enough remaining leave days")

        # Record the used days
        self._set_used_days(employee, year, used_so_far + working_days)

        return working_days

    def remaining(self, employee: str, year: int) -> int:
        used = self._get_used_days(employee, year)
        return self.days_per_year - used
